{"path": "csvfix/impl.py", "content": "def parse(line):
    """Split a CSV line into fields.

    Each field is trimmed of surrounding whitespace. A line that does not
    contain exactly three columns is invalid and returns ``None``.
    """
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 3:
        return None
    return fields


def total(rows):
    """Sum the amount (third) column, skipping blank amount fields."""
    return sum(int(r[2]) for r in rows if len(r) > 2 and r[2].strip())
"}

{"path": "rules/engine.py", "content": "def evaluate(rules, facts):
    """Evaluate a rule against boolean ``facts``.

    Supports ``{"all": [...]}`` (every referenced fact is truthy) and
    ``{"any": [...]}`` (at least one referenced fact is truthy). An unknown
    fact name is treated as ``False``.
    """
    if "all" in rules:
        return all(bool(facts.get(name, False)) for name in rules["all"])
    if "any" in rules:
        return any(bool(facts.get(name, False)) for name in rules["any"])
    return False
